def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors={v for row in grid for v in row if v!=bg}
    mark=min(colors,key=lambda v:sum(x==v for row in grid for x in row))
    for r in range(h):
        pts=[c for c,v in enumerate(grid[r]) if v==mark]
        for a,b in zip(pts,pts[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        pts=[r for r in range(h) if grid[r][c]==mark]
        for a,b in zip(pts,pts[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    return out
